// 颜色签名：4 桶(红/绿/蓝/无彩) x 8 位；未知类返回 0
module tile_color_tbl (
    input  wire [7:0]  I_cls,
    output reg  [31:0] O_sig
);
    always @(*) begin
        case (I_cls)
            8'd1  : O_sig = 32'h12005d90;   // Pin1
            8'd2  : O_sig = 32'h00004fb0;   // Pin2
            8'd3  : O_sig = 32'h2a0028ad;   // Pin3
