            8'd18 : O_sig = 32'h505a0055;   // Sou9
            8'd19 : O_sig = 32'h3b0000c4;   // Man1
            8'd20 : O_sig = 32'h210000de;   // Man2
            8'd21 : O_sig = 32'h200000df;   // Man3
            8'd22 : O_sig = 32'h190000e6;   // Man4
            8'd23 : O_sig = 32'h180000e7;   // Man5
